<?php
require_once __DIR__.'/../v7-layout.php';require_once __DIR__.'/../../php/finance_service_v7.php';cfRequirePermission('finance.view');
$error='';$message='';$rows=[];$metrics=[];
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
  cfRequirePermission('finance.manage');
  if(!cfCheckCsrf((string)($_POST['csrf_token']??''))){$error='Token CSRF inválido.';}
  else try{$id=cfFinanceCreateDraft(cfDb(),$_POST,cfActor());header('Location: lancamentos-v7.php?criado='.$id);exit;}catch(InvalidArgumentException|DomainException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Finance V7: '.$e->getMessage());$error='Cadastro indisponível. Migre e homologue o banco antes de habilitar lançamentos.';}
}
try{$db=cfDb();$result=$db->query("SELECT id,entry_type,description,amount,due_date,status,created_at FROM finance_entries_v7 ORDER BY id DESC LIMIT 80");$rows=$result->fetch_all(MYSQLI_ASSOC);$metrics=$db->query("SELECT COUNT(*) total, COALESCE(SUM(status='rascunho'),0) drafts FROM finance_entries_v7")->fetch_assoc();}catch(Throwable $e){error_log('Finance list V7: '.$e->getMessage());$error=$error?:'Livro interno indisponível. Verifique o banco.';}
$enabled=filter_var(getenv('FINANCE_V7_WRITE_ENABLED')?:'0',FILTER_VALIDATE_BOOLEAN);
cfV7Head('Livro financeiro interno','Rascunhos e controles administrativos. Não representa cobranças pagas ou recebimentos de gateway.');
if($error)cfV7Alert($error,'danger');if(isset($_GET['criado']))cfV7Alert('Rascunho interno registrado. Nenhuma transação bancária foi realizada.','success');
?><section class="cf-v7-grid"><?php cfV7Stat('Lançamentos registrados',$metrics['total']??'—');cfV7Stat('Rascunhos',$metrics['drafts']??'—');?></section>
<div class="cf-v7-columns"><section class="cf-v7-panel"><h2>Histórico de lançamentos</h2><div class="cf-v7-tablewrap"><table><thead><tr><th>ID</th><th>Tipo</th><th>Descrição</th><th>Valor</th><th>Vencimento</th><th>Situação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=cfEsc($r['id'])?></td><td><?=cfEsc($r['entry_type'])?></td><td><?=cfEsc($r['description'])?></td><td>R$ <?=cfEsc(number_format((float)$r['amount'],2,',','.'))?></td><td><?=cfEsc($r['due_date'])?></td><td><span class="cf-v7-chip"><?=cfEsc($r['status'])?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Nenhum lançamento disponível.</td></tr><?php endif;?></tbody></table></div></section>
<section class="cf-v7-panel"><h2>Novo rascunho</h2><?php if(!$enabled):?><div class="cf-v7-alert" role="status">Gravação desabilitada até testes com MySQL. Defina FINANCE_V7_WRITE_ENABLED=1 apenas em ambiente homologado.</div><?php endif;?>
<?php if(cfCan('finance.manage',$_SESSION)):?><form method="post" class="cf-v7-stack"><input type="hidden" name="csrf_token" value="<?=cfEsc(cfCsrfToken())?>"><input type="hidden" name="idempotency_key" value="<?=cfEsc(bin2hex(random_bytes(32)))?>"><label>Tipo<select class="cf-v7-select" name="entry_type" required><option value="receber">Receber</option><option value="pagar">Pagar</option></select></label><label>Descrição<input class="cf-v7-input" maxlength="240" name="description" required></label><label>Valor em reais (ex.: 120.50)<input class="cf-v7-input" name="amount" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required></label><label>ID do cliente (opcional)<input class="cf-v7-input" type="number" min="1" name="client_id"></label><label>Vencimento (opcional)<input class="cf-v7-input" type="date" name="due_date"></label><button class="cf-v7-btn cf-v7-btn-primary" type="submit" <?=$enabled?'':'disabled'?>>Salvar rascunho interno</button></form><?php else:?><p>Acesso somente de leitura para este perfil.</p><?php endif;?></section></div>
<?php cfV7Foot(); ?>
